import {createStudy,canvasSurface,seededRandom,clamp,downloadCanvas} from './core.js';
const study=createStudy({id:14,title:'Magnetic Field',category:'Physics / Field',accent:'#b7f2cf',background:'#031a1c',foreground:'#d4f3e4'});
const canvas=document.querySelector('#magnetic-canvas'),surface=canvasSurface(canvas,{maxDpr:1.5});
let particles=[],poles=[],fieldPath=null,strength=70,reversed=false,drag=false;
function field(x,y){let fx=0,fy=0;for(const p of poles){const dx=x-p.x,dy=y-p.y,d2=dx*dx+dy*dy+900,sign=p.sign*(reversed&&p===poles[0]?-1:1);fx+=dx/d2*sign;fy+=dy/d2*sign}return{x:fx,y:fy}}
function rebuild(){fieldPath=new Path2D();const{width:w,height:h}=surface;const source=poles[0];for(let i=0;i<44;i++){const angle=i/44*Math.PI*2;let x=source.x+Math.cos(angle)*16,y=source.y+Math.sin(angle)*16;fieldPath.moveTo(x,y);for(let step=0;step<160;step++){const f=field(x,y),length=Math.hypot(f.x,f.y)||.001,direction=reversed?-1:1;x+=f.x/length*5*direction;y+=f.y/length*5*direction;fieldPath.lineTo(x,y);if(x<-20||x>w+20||y<-20||y>h+20)break;if(Math.hypot(x-poles[1].x,y-poles[1].y)<15)break}}}
function reset(restoreControls=false){if(restoreControls){strength=70;document.querySelector('#magnetic-force').value=70;document.querySelector('#magnetic-value').textContent=70}canvas.style.cursor='default';document.querySelector('#magnetic-status').textContent='Drag the bright pole. The field redraws around you.';const{width:w,height:h}=surface;const rand=seededRandom(14014);poles=[{x:w*.58,y:h*.45,sign:1},{x:w*.82,y:h*.63,sign:-1}];if(w<600)poles=[{x:w*.45,y:h*.43,sign:1},{x:w*.75,y:h*.64,sign:-1}];particles=Array.from({length:180},()=>({x:rand()*w,y:rand()*h,age:rand()*8,life:5+rand()*10,history:[],speed:.65+rand()*.7}));reversed=false;drag=false;document.querySelector('#magnetic-polarity').setAttribute('aria-pressed','false');rebuild();draw(0);}
function draw(time){const{ctx,width:w,height:h}=surface;if(!ctx)return;ctx.clearRect(0,0,w,h);ctx.fillStyle='#031a1c';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#4b9c8a35';ctx.lineWidth=.7;ctx.stroke(fieldPath);const step=w<600?38:47;ctx.strokeStyle='#82b5a02b';ctx.lineWidth=.6;for(let y=step/2;y<h;y+=step)for(let x=step/2;x<w;x+=step){const f=field(x,y),length=Math.hypot(f.x,f.y)||.001,dx=f.x/length*8,dy=f.y/length*8;ctx.beginPath();ctx.moveTo(x-dx,y-dy);ctx.lineTo(x+dx,y+dy);ctx.lineTo(x+dx-dx*.35+dy*.3,y+dy-dy*.35-dx*.3);ctx.stroke()}for(let i=0;i<particles.length;i++){const p=particles[i];ctx.beginPath();p.history.forEach((q,j)=>j?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y));ctx.strokeStyle=i%4===0?'#d8ffe8a6':'#7fcbb970';ctx.lineWidth=i%7===0?1.6:.8;ctx.stroke();ctx.beginPath();ctx.arc(p.x,p.y,i%7===0?1.8:1,0,Math.PI*2);ctx.fillStyle=i%4===0?'#f0fff0':'#a4e1cc';ctx.fill()}for(let i=0;i<poles.length;i++){const p=poles[i],r=i===0?12:9;const glow=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,58);glow.addColorStop(0,'#b7f2cf33');glow.addColorStop(1,'#b7f2cf00');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(p.x,p.y,58,0,Math.PI*2);ctx.fill();ctx.strokeStyle=i===0?'#d4ffe3':'#729e93';ctx.lineWidth=1;ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(p.x-4,p.y);ctx.lineTo(p.x+4,p.y);if(i===0&&!reversed){ctx.moveTo(p.x,p.y-4);ctx.lineTo(p.x,p.y+4)}ctx.stroke();ctx.beginPath();ctx.arc(p.x,p.y,r+8+(drag&&i===0?3:0),0,Math.PI*2);ctx.strokeStyle='#9fd7bd33';ctx.stroke()}}
function frame({dt,time}){if(dt>0){const{width:w,height:h}=surface;for(let i=0;i<particles.length;i++){const p=particles[i],f=field(p.x,p.y),length=Math.hypot(f.x,f.y)||.001,speed=(24+strength*.8)*p.speed;p.x+=f.x/length*speed*dt;p.y+=f.y/length*speed*dt;p.age+=dt;p.history.push({x:p.x,y:p.y});if(p.history.length>15)p.history.shift();if(p.age>p.life||p.x<-10||p.x>w+10||p.y<-10||p.y>h+10||Math.hypot(p.x-poles[1].x,p.y-poles[1].y)<8){const angle=(i*.61803398875+time*.03)%1*Math.PI*2;p.x=poles[0].x+Math.cos(angle)*17;p.y=poles[0].y+Math.sin(angle)*17;p.age=0;p.history=[]}}}draw(time)}
function point(event){const r=canvas.getBoundingClientRect();return{x:event.clientX-r.left,y:event.clientY-r.top}}
canvas.addEventListener('pointerdown',event=>{const p=point(event);if(Math.hypot(p.x-poles[0].x,p.y-poles[0].y)<90){drag=true;canvas.setPointerCapture(event.pointerId);canvas.style.cursor='grabbing'}});canvas.addEventListener('pointermove',event=>{const p=point(event);if(drag){poles[0].x=clamp(p.x,25,surface.width-25);poles[0].y=clamp(p.y,25,surface.height-25);rebuild();study.invalidate()}else canvas.style.cursor=Math.hypot(p.x-poles[0].x,p.y-poles[0].y)<90?'grab':'default'});for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,()=>{drag=false;canvas.style.cursor='default'});
document.querySelector('#magnetic-force').addEventListener('input',event=>{strength=+event.target.value;document.querySelector('#magnetic-value').textContent=strength;study.invalidate()});document.querySelector('#magnetic-polarity').addEventListener('click',()=>{reversed=!reversed;document.querySelector('#magnetic-polarity').setAttribute('aria-pressed',String(reversed));document.querySelector('#magnetic-status').textContent=reversed?'Polarity reversed. A different field, a different rhythm.':'Two polarities. Follow the connection.';rebuild();study.invalidate()});
study.setReset(()=>reset(true));study.setExport(()=>downloadCanvas(canvas,'14-magnetic-field.png'));study.onResize(reset);study.onFrame(frame);study.cleanup(()=>surface.dispose());reset();
